async function readPdf(file) {
  const document2 = await getDocument({ data: new Uint8Array(await file.arrayBuffer()), disableWorker: true }).promise;
  const pages = [];
  for (let pageNumber = 1; pageNumber <= document2.numPages; pageNumber++) {
    const page = await document2.getPage(pageNumber);
    const content = await page.getTextContent();
    pages.push(content.items.map((item) => item.str || "").join(" "));
  }
  return pages.map((page, index) => `\u7B2C ${index + 1} \u9875
${page}`).join("\n\n");
}
async function readDocx(file) {
  const result = await mammoth.extractRawText({ arrayBuffer: await file.arrayBuffer() });
  return result.value;
}
async function readWorkbook(file) {
  const workbook = readSync(await file.arrayBuffer(), { type: "array", cellDates: true });
  return workbook.SheetNames.map((name) => {
    const sheet = workbook.Sheets[name];
    return `\u5DE5\u4F5C\u8868\uFF1A${name}
${utils.sheet_to_csv(sheet, { blankrows: false })}`;
  }).join("\n\n");
}
